<template><section class="bio-nexus-panel laboratory-panel"><div class="bio-nexus-panel-heading"><div><p class="bio-nexus-panel-eyebrow">Identidad visual</p><h3>Logo del laboratorio</h3></div></div><div class="logo-layout"><div class="logo-preview"><img v-if="logoUrl" :src="logoUrl" alt="Logo actual" :style="previewStyle"><span v-else>Sin logo</span></div><div class="logo-controls"><BioNexusFormField label="Altura mÃ¡xima" field-id="logo-height"><input v-model.number="model.max_height_logo" class="bio-nexus-field" type="range" min="0" max="200" step="5"></BioNexusFormField><output>{{ model.max_height_logo }} px</output><BioNexusFormField label="Ancho mÃ¡ximo" field-id="logo-width"><input v-model.number="model.max_width_logo" class="bio-nexus-field" type="range" min="0" max="200" step="5"></BioNexusFormField><output>{{ model.max_width_logo }} px</output><input ref="fileInput" class="file-input" type="file" accept="image/png,image/jpeg,image/webp" @change="selectFile"><BioNexusActionButton variant="secondary" :disabled="disabled" @click="fileInput?.click()">Seleccionar imagen</BioNexusActionButton></div></div></section></template>
<script setup>import{computed,ref}from"vue";import BioNexusActionButton from"@/components/ui/BioNexusActionButton.vue";import BioNexusFormField from"@/components/ui/BioNexusFormField.vue";const props=defineProps({model:{type:Object,required:true},disabled:{type:Boolean,default:false}});const emit=defineEmits(["upload"]);const fileInput=ref(null);const logoUrl=computed(()=>props.model.logo?"/images/"+props.model.logo:"");const previewStyle=computed(()=>({maxHeight:String(props.model.max_height_logo||200)+"px",maxWidth:String(props.model.max_width_logo||200)+"px"}));function selectFile(event){const file=event.target.files?.[0];if(file)emit("upload",file);event.target.value="";}</script>
<style scoped>.logo-layout{display:grid;grid-template-columns:minmax(220px,280px) minmax(280px,1fr);gap:var(--bio-nexus-space-5);align-items:center}.logo-preview{display:grid;place-items:center;min-height:220px;border:1px dashed var(--bio-nexus-color-border-strong);border-radius:var(--bio-nexus-radius-md);background:var(--bio-nexus-color-surface-soft);color:var(--bio-nexus-color-text-muted);overflow:hidden}.logo-preview img{object-fit:contain}.logo-controls{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:var(--bio-nexus-space-3);align-items:center}.logo-controls .bio-nexus-action-button{grid-column:1/-1;justify-self:start}.file-input{display:none}@media(max-width:720px){.logo-layout,.logo-controls{grid-template-columns:1fr}}</style>